create table order_items(
  order_id integer, product_id integer,
  product_name text, quantity integer
);
insert into order_items values
  (1,7,'Drill',2),(2,7,'Drill',1),(3,9,'Saw',3);

select product_id, product_name
from order_items;

-- before: one table, key is (order_id, product_id)
create table order_items(
  order_id integer, product_id integer,
  product_name text, product_price numeric,
  quantity integer,
  primary key (order_id, product_id)
);

-- after: product facts move to their own table
create table products(
  product_id integer primary key,
  product_name text, product_price numeric
);
create table order_lines(
  order_id integer, product_id integer, quantity integer,
  primary key (order_id, product_id)
);

